WHERE DEL_FLAG = '0'

    AND (ENTERPRISE_ID = #{queryVo.enterpriseId} OR ENTERPRISE_ID = 'ALL')


    AND BUDGET_TYPE = #{queryVo.budgetType}


    AND BUDGET_NAME LIKE '%' || #{queryVo.budgetName} || '%'


    AND BUDGET_YEAR = #{queryVo.budgetYear}


    AND BUDGET_STATUS = #{queryVo.budgetStatus}


    AND APPROVAL_STATUS = #{queryVo.approvalStatus}


    AND BUDGET_MANAGER = #{queryVo.budgetManager}


    AND BUDGET_DEPARTMENT = #{queryVo.budgetDepartment}


    AND RISK_LEVEL = #{queryVo.riskLevel}

